SELECT 't301' AS kind,CAST(a AS TEXT)||','||CAST(b AS TEXT)||','||CAST(c AS TEXT) AS detail FROM t301 UNION ALL SELECT 't302',CAST(x AS TEXT)||','||CAST(y AS TEXT) FROM t302 UNION ALL SELECT 'schema',type||':'||name||':'||tbl_name FROM sqlite_master WHERE name IN ('t301','t301c','t302') UNION ALL SELECT 'stat',tbl||':'||COALESCE(idx,'')||':'||stat FROM sqlite_stat1 ORDER BY kind,detail;